describe('Mobile Responsive Sauce Demo Store', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should display inventory page on mobile portrait viewport and show burger menu button', () => {
    // Set viewport to mobile portrait
    cy.viewport('iphone-x');

    // Verify viewport size
    cy.window().then((win) => {
      expect(win.innerWidth).to.equal(375);
      expect(win.innerHeight).to.equal(812);
    });

    // Verify login button is visible
    cy.get('[data-testid="login-btn"]').should('be.visible');

    // Verify burger menu button is visible
    cy.get('[data-testid="react-burger-menu-btn"]').should('be.visible');

    // Verify burger menu opens
    cy.get('[data-testid="react-burger-menu-btn"]').click();
    cy.get('[data-testid="bm-menu"]').should('be.visible');

    // Verify logout link is visible inside the side menu
    cy.get('[data-testid="logout-sidebar-link"]').should('be.visible');
  });

  it('should handle burger menu click and logout link visibility on mobile portrait', () => {
    // Set viewport to mobile portrait
    cy.viewport('iphone-x');

    // Verify burger menu button is visible
    cy.get('[data-testid="react-burger-menu-btn"]').should('be.visible');

    // Click burger menu button
    cy.get('[data-testid="react-burger-menu-btn"]').click();

    // Verify side menu is open
    cy.get('[data-testid="bm-menu"]').should('be.visible');

    // Verify logout link is visible inside the side menu
    cy.get('[data-testid="logout-sidebar-link"]').should('be.visible');

    // Click logout link
    cy.get('[data-testid="logout-sidebar-link"]').click();

    // Verify logout confirmation appears
    cy.get('[data-testid="logout-confirmation"]').should('be.visible');

    // Verify burger menu closes
    cy.get('[data-testid="react-burger-menu-btn"]').should('not.be.visible');
  });
});
